<template><Layout><div class="breadcrumb"><Link :href="route('orders.index')">Orders</Link><span>›</span>#{{ order.code }}</div><div class="page-header order-detail-head"><div><div class="eyebrow">ORDER DETAILS</div><h1>#{{ order.code }}</h1><p>Placed {{ fullDate(order.created_at) }}</p></div><span class="status-pill detail-status" :class="statusClass(order.status)">{{ readable(order.status) }}</span></div><section class="order-detail-grid"><div class="detail-main"><article class="detail-card"><header><h2>Order progress</h2><p>Current transaction status</p></header><div v-if="rejected" class="rejection-alert"><b>×</b><div><strong>{{ readable(order.status) }}</strong><p>{{ order.reject_note||'No rejection reason was provided.' }}</p></div></div><div v-else class="status-timeline"><div v-for="(step,i) in steps" :key="step.key" :class="{done:i<=currentStep,current:i===currentStep}"><span>{{ i<currentStep?'✓':i+1 }}</span><div><strong>{{ step.label }}</strong><small>{{ i<=currentStep?(i===currentStep?'Current status':'Completed'):'Waiting' }}</small></div></div></div></article><article class="detail-card"><header><h2>Order information</h2></header><div class="info-grid"><div><span>Product</span><strong>{{ order.product_details?.name||'Unavailable' }}</strong></div><div><span>Condition</span><strong>{{ order.product_details?.condition||'—' }}</strong></div><div><span>Quantity</span><strong>{{ order.quantity }}</strong></div><div><span>Unit price</span><strong>{{ money(order.product_details?.price||0) }}</strong></div><div><span>Payment method</span><strong>{{ order.payment?.name||'Not selected' }}</strong></div><div><span>Order total</span><strong class="total-value">{{ money(order.total_price) }}</strong></div></div><div v-if="order.note" class="order-note"><span>Buyer note</span><p>{{ order.note }}</p></div></article><article v-if="order.payment_screenshot" class="detail-card"><header><h2>Payment proof</h2></header><a :href="order.payment_screenshot" target="_blank" class="payment-proof"><img :src="order.payment_screenshot"/><span>Open full image ↗</span></a></article></div><aside class="detail-side"><PersonCard title="Buyer" :person="order.buyer_details"/><PersonCard title="Seller" :person="order.seller_details"/><article class="detail-card compact-card"><header><h2>Summary</h2></header><div class="summary-lines"><p><span>Subtotal</span><b>{{ money(order.total_price) }}</b></p><p><span>Quantity</span><b>× {{ order.quantity }}</b></p><p class="grand-total"><span>Total</span><b>{{ money(order.total_price) }}</b></p></div></article></aside></section></Layout></template>
<script setup>import{computed}from'vue';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';import PersonCard from'../Components/PersonCard.vue';const props=defineProps({order:Object});const steps=[{key:'order-pending',label:'Order placed'},{key:'order-accepted',label:'Order accepted'},{key:'payment-pending',label:'Payment submitted'},{key:'payment-accepted',label:'Payment accepted'},{key:'delivered',label:'Delivered'},{key:'received',label:'Received'}];const rejected=computed(()=>props.order.status.includes('rejected')),currentStep=computed(()=>{if(props.order.status==='on-hold')return 0;return Math.max(0,steps.findIndex(s=>s.key===props.order.status))});const readable=s=>s.replaceAll('-',' ').replace(/\b\w/g,l=>l.toUpperCase()),statusClass=s=>s.includes('reject')?'status-red':['received','delivered'].includes(s)?'status-green':'status-amber';const money=v=>new Intl.NumberFormat('en-US').format(v)+' Ks',fullDate=d=>new Intl.DateTimeFormat('en',{dateStyle:'long',timeStyle:'short'}).format(new Date(d));</script>
